<?php require __DIR__.'/../includes/app.php';$title='Inicio';$subtitle='Resumen de lo que está pasando';$me=require_admin();$pdo=db();$stats=['Actividades'=>(int)$pdo->query('SELECT COUNT(*) FROM actividades')->fetchColumn(),'Publicadas'=>(int)$pdo->query("SELECT COUNT(*) FROM actividades WHERE estado='publicada'")->fetchColumn(),'Inscripciones'=>(int)$pdo->query("SELECT COUNT(*) FROM inscripciones WHERE estado='confirmada'")->fetchColumn(),'Cupos totales'=>(int)$pdo->query('SELECT COALESCE(SUM(capacidad),0) FROM cupos WHERE habilitado=1')->fetchColumn()];$last=$pdo->query("SELECT i.familia,a.nombre actividad,co.nombre comision,t.hora_inicio,t.hora_fin,i.creado_en FROM inscripciones i JOIN actividades a ON a.id=i.actividad_id JOIN comisiones co ON co.id=i.comision_id JOIN turnos t ON t.id=i.turno_id WHERE i.estado='confirmada' ORDER BY i.id DESC LIMIT 8")->fetchAll();require __DIR__.'/../includes/admin-header.php';?><section class="panel"><div class="panelhead"><h2>¿Qué quieres hacer?</h2></div><div class="actions"><a class="btn" href="<?=e(url('admin/actividades.php?nueva=1'))?>">+ Nueva actividad</a><a class="btn ghost" href="<?=e(url('admin/estructura.php'))?>">Comisiones, turnos y cupos</a><a class="btn ghost" href="<?=e(url('admin/inscripciones.php'))?>">Ver inscripciones</a></div></section><section class="cards"><?php foreach($stats as $k=>$v):?><div class="stat"><b><?=$v?></b><span><?=e($k)?></span></div><?php endforeach;?></section><section class="panel"><div class="panelhead"><h2>Últimas inscripciones</h2><a class="btn" href="<?=e(url('admin/inscripciones.php'))?>">Ver todas</a></div><table><tr><th>Familia</th><th>Actividad</th><th>Comisión</th><th>Turno</th><th>Fecha</th></tr><?php if(!$last):?><tr><td colspan="5" class="muted">Aún no hay inscripciones.</td></tr><?php endif;?><?php foreach($last as $r):?><tr><td><?=e($r['familia'])?></td><td><?=e($r['actividad'])?></td><td><?=e($r['comision'])?></td><td><?=e(substr($r['hora_inicio'],0,5).'-'.substr($r['hora_fin'],0,5))?></td><td><?=e(fmt_dt($r['creado_en']))?></td></tr><?php endforeach;?></table></section><?php require __DIR__.'/../includes/admin-footer.php';
